package org.cbhs.bank;

import io.javalin.Javalin;
import io.javalin.http.Context;
import io.javalin.http.staticfiles.Location;
import io.javalin.json.JavalinJackson;
import org.cbhs.bank.model.Account;
import org.cbhs.bank.model.Bank;
import org.cbhs.bank.model.Transaction;

import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Teacher-owned HTTP and JSON glue. Students do not edit this file.
 */
public class App {
    public static final String DATA_FILE = "data/accounts.txt";

    private static final Bank bank = new Bank();

    public static void main(String[] args) {
        loadSeed();

        Javalin app = Javalin.create(config -> {
            config.staticFiles.add("/public", Location.CLASSPATH);
            config.jsonMapper(new JavalinJackson());
            config.showJavalinBanner = false;
        });

        app.get("/", ctx -> ctx.html(loadPage("home.html")));
        app.get("/accounts", ctx -> ctx.html(loadPage("accounts.html")));
        app.get("/account", ctx -> ctx.html(loadPage("account.html")));
        app.get("/new-account", ctx -> ctx.html(loadPage("new-account.html")));
        app.get("/transfer", ctx -> ctx.html(loadPage("transfer.html")));
        app.get("/admin", ctx -> ctx.html(loadPage("admin.html")));

        app.get("/api/stats", App::stats);
        app.get("/api/accounts", App::listAccounts);
        app.get("/api/accounts/{number}", App::oneAccount);
        app.post("/api/accounts", App::openAccount);
        app.post("/api/accounts/{number}/deposit", App::deposit);
        app.post("/api/accounts/{number}/withdraw", App::withdraw);
        app.post("/api/transfer", App::transfer);
        app.post("/api/interest", App::interest);
        app.post("/api/reload", App::reload);

        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "8082"));
        app.start(port);
        System.out.println("CBHS Bank running at http://localhost:" + port);
    }

    private static void loadSeed() {
        try {
            bank.loadFromFile(DATA_FILE);
        } catch (IOException e) {
            System.out.println("Could not load " + DATA_FILE + ". Starting with no accounts.");
            System.out.println("Run the app from the cbhs-bank folder.");
        }
    }

    private static void stats(Context ctx) {
        Map<String, Object> body = new LinkedHashMap<String, Object>();
        body.put("accountCount", bank.countAccounts());
        body.put("totalAssets", bank.totalAssets());
        body.put("averageBalance", bank.averageBalance());
        ctx.json(body);
    }

    private static void listAccounts(Context ctx) {
        String name = ctx.queryParam("name");
        ArrayList<Account> list;
        if (name != null && name.length() > 0) {
            list = bank.findAccountsByName(name);
        } else {
            list = bank.getAccounts();
        }
        ArrayList<Map<String, Object>> accounts = new ArrayList<Map<String, Object>>();
        for (int i = 0; i < list.size(); i++) {
            accounts.add(accountJson(list.get(i), false));
        }
        Map<String, Object> body = new LinkedHashMap<String, Object>();
        body.put("accounts", accounts);
        ctx.json(body);
    }

    private static void oneAccount(Context ctx) {
        Account account = bank.findAccount(ctx.pathParamAsClass("number", Integer.class).get());
        if (account == null) {
            ctx.status(404);
            ctx.json(error("Account not found"));
            return;
        }
        ctx.json(accountJson(account, true));
    }

    private static void openAccount(Context ctx) {
        Map<String, Object> input = readBody(ctx);
        String ownerName = asString(input.get("ownerName"));
        String accountType = asString(input.get("accountType"));
        double starting = asDouble(input.get("startingBalance"));

        if (ownerName.length() == 0) {
            ctx.json(fail("Owner name is required"));
            return;
        }
        if (!accountType.equals("checking") && !accountType.equals("savings")) {
            ctx.json(fail("Account type must be checking or savings"));
            return;
        }
        if (starting < 0) {
            ctx.json(fail("Starting balance cannot be negative"));
            return;
        }

        int number = bank.nextAccountNumber();
        Account account = new Account(number, ownerName, accountType, starting);
        if (starting > 0) {
            account.addTransaction(new Transaction("deposit", starting, "Opening balance", today()));
        }
        bank.addAccount(account);
        ctx.json(accountJson(account, true));
    }

    private static void deposit(Context ctx) {
        int number = ctx.pathParamAsClass("number", Integer.class).get();
        Map<String, Object> input = readBody(ctx);
        double amount = asDouble(input.get("amount"));
        String note = asString(input.get("note"));
        if (note.length() == 0) {
            note = "Deposit";
        }

        Account account = bank.findAccount(number);
        if (account == null) {
            ctx.json(fail("Account not found"));
            return;
        }
        if (amount <= 0) {
            ctx.json(fail("Invalid amount"));
            return;
        }
        boolean ok = bank.deposit(number, amount, note, today());
        if (!ok) {
            ctx.json(fail("Deposit failed"));
            return;
        }
        ctx.json(okBalance(account.getBalance()));
    }

    private static void withdraw(Context ctx) {
        int number = ctx.pathParamAsClass("number", Integer.class).get();
        Map<String, Object> input = readBody(ctx);
        double amount = asDouble(input.get("amount"));
        String note = asString(input.get("note"));
        if (note.length() == 0) {
            note = "Withdraw";
        }

        Account account = bank.findAccount(number);
        if (account == null) {
            ctx.json(fail("Account not found"));
            return;
        }
        if (amount <= 0) {
            ctx.json(fail("Invalid amount"));
            return;
        }
        if (amount > account.getBalance()) {
            ctx.json(fail("Insufficient funds"));
            return;
        }
        boolean ok = bank.withdraw(number, amount, note, today());
        if (!ok) {
            ctx.json(fail("Withdraw failed"));
            return;
        }
        ctx.json(okBalance(account.getBalance()));
    }

    private static void transfer(Context ctx) {
        Map<String, Object> input = readBody(ctx);
        int fromNumber = (int) asDouble(input.get("fromNumber"));
        int toNumber = (int) asDouble(input.get("toNumber"));
        double amount = asDouble(input.get("amount"));
        String note = asString(input.get("note"));
        if (note.length() == 0) {
            note = "Transfer";
        }

        if (fromNumber == toNumber) {
            ctx.json(fail("Choose two different accounts"));
            return;
        }
        if (bank.findAccount(fromNumber) == null || bank.findAccount(toNumber) == null) {
            ctx.json(fail("Account not found"));
            return;
        }
        if (amount <= 0) {
            ctx.json(fail("Invalid amount"));
            return;
        }
        Account from = bank.findAccount(fromNumber);
        if (amount > from.getBalance()) {
            ctx.json(fail("Insufficient funds"));
            return;
        }
        boolean ok = bank.transfer(fromNumber, toNumber, amount, note, today());
        if (!ok) {
            ctx.json(fail("Transfer failed"));
            return;
        }
        ctx.json(okOnly());
    }

    private static void interest(Context ctx) {
        int updated = bank.applyInterest(today());
        Map<String, Object> body = okOnly();
        body.put("updated", updated);
        ctx.json(body);
    }

    private static void reload(Context ctx) {
        try {
            bank.loadFromFile(DATA_FILE);
        } catch (IOException e) {
            ctx.json(fail("Could not load " + DATA_FILE));
            return;
        }
        Map<String, Object> body = okOnly();
        body.put("accountCount", bank.countAccounts());
        ctx.json(body);
    }

    private static Map<String, Object> accountJson(Account account, boolean includeTransactions) {
        Map<String, Object> json = new LinkedHashMap<String, Object>();
        json.put("accountNumber", account.getAccountNumber());
        json.put("ownerName", account.getOwnerName());
        json.put("accountType", account.getAccountType());
        json.put("balance", account.getBalance());
        if (includeTransactions) {
            ArrayList<Map<String, Object>> txns = new ArrayList<Map<String, Object>>();
            ArrayList<Transaction> list = account.getTransactions();
            for (int i = 0; i < list.size(); i++) {
                Transaction t = list.get(i);
                Map<String, Object> row = new LinkedHashMap<String, Object>();
                row.put("type", t.getType());
                row.put("amount", t.getAmount());
                row.put("note", t.getNote());
                row.put("stamp", t.getStamp());
                txns.add(row);
            }
            json.put("transactions", txns);
        }
        return json;
    }

    @SuppressWarnings("unchecked")
    private static Map<String, Object> readBody(Context ctx) {
        if (ctx.body().length() == 0) {
            return new LinkedHashMap<String, Object>();
        }
        return ctx.bodyAsClass(Map.class);
    }

    private static Map<String, Object> okOnly() {
        Map<String, Object> body = new LinkedHashMap<String, Object>();
        body.put("ok", true);
        return body;
    }

    private static Map<String, Object> okBalance(double balance) {
        Map<String, Object> body = okOnly();
        body.put("balance", balance);
        return body;
    }

    private static Map<String, Object> fail(String message) {
        Map<String, Object> body = new LinkedHashMap<String, Object>();
        body.put("ok", false);
        body.put("error", message);
        return body;
    }

    private static Map<String, Object> error(String message) {
        Map<String, Object> body = new LinkedHashMap<String, Object>();
        body.put("error", message);
        return body;
    }

    private static String asString(Object value) {
        if (value == null) {
            return "";
        }
        return String.valueOf(value).trim();
    }

    private static double asDouble(Object value) {
        if (value == null) {
            return 0;
        }
        if (value instanceof Number) {
            return ((Number) value).doubleValue();
        }
        try {
            return Double.parseDouble(String.valueOf(value));
        } catch (NumberFormatException e) {
            return 0;
        }
    }

    private static String today() {
        return LocalDate.now().toString();
    }

    private static String loadPage(String name) {
        try (InputStream in = App.class.getResourceAsStream("/public/pages/" + name)) {
            if (in == null) {
                return "<h1>CBHS Bank</h1><p>Page not found.</p>";
            }
            return new String(in.readAllBytes(), StandardCharsets.UTF_8);
        } catch (IOException e) {
            return "<h1>CBHS Bank</h1><p>Could not load page.</p>";
        }
    }
}
